/**
 * AdScript - Complete script for the selected scenario
 *
 * Generated by AI from the selected scenario and creative brief.
 * Includes timed narration lines for subtitle generation.
 */
export interface NarrationLine {
  /** Line text */
  text: string;

  /** Estimated duration in seconds */
  estimatedDurationSec: number;

  /** Speaker/voice direction for Veo */
  speaker?: string;

  /** Scene number this line belongs to (MVP: always 1) */
  scene: number;
}

export interface AdScript {
  /** Job identifier */
  jobId: string;

  /** Selected scenario ID */
  scenarioId: number;

  /** Script title */
  title: string;

  /** Opening hook line */
  hook: string;

  /** Timed narration lines */
  voiceoverLines: NarrationLine[];

  /** Call-to-action line */
  cta: string;

  /** Full script text (concatenated) */
  fullText: string;

  /** Visual description for scene planning */
  visualDescription?: string;

  /** Total estimated duration */
  totalEstimatedDuration: number;

  /** Timestamp when script was generated */
  generatedAt: Date;
}
